import React from 'react';
import './Menu.css';

const Menu = ({ addToCart }) => {
  // Sample menu data - replace with your actual data
  const menuItems = [
    {
      id: 1,
      name: 'Kopta',
      price: 250,
      description: 'Tender chicken in rich tomato butter sauce',
      image: 'https://images.unsplash.com/photo-1603894584373-5ac82b2ae398'
    },
    {
      id: 2,
      name: 'Dal Makhani',
      price: 180,
      description: 'Creamy black lentils slow cooked overnight',
      image: 'https://images.unsplash.com/photo-1601050690597-df0568f70950'
    },
    {
      id: 3,
      name: 'Paneer Tikka',
      price: 220,
      description: 'Grilled cottage cheese with spices',
      image: 'https://images.unsplash.com/photo-1601050690597-df0568f70950'
    },
    {
      id: 4,
      name: 'Rogan Josh',
      price: 280,
      description: 'Aromatic lamb curry from Kashmir',
      image: 'https://images.unsplash.com/photo-1603360946369-dc9bb6258143'
    },
    {
      id: 5,
      name: 'Biryani',
      price: 240,
      description: 'Fragrant rice with spices and vegetables',
      image: 'https://images.unsplash.com/photo-1631515243349-e0cb75fb8d3a'
    },
    {
      id: 6,
      name: 'Gulab Jamun',
      price: 120,
      description: 'Sweet fried dough balls in sugar syrup',
      image: 'https://images.unsplash.com/photo-1601050690117-94f5f6fa3bd0'
    }
  ];

  return (
    <div className="menu-page">
      <div className="menu-header">
        <h1>Hotel Shyam Special Menu</h1>
        <p>Authentic flavors crafted with traditional recipes</p>
      </div>

      <div className="menu-items-container">
        {menuItems.map(item => (
          <div key={item.id} className="menu-item">
            <div className="item-image">
              <img src={item.image} alt={item.name} />
            </div>
            <div className="item-details">
              <h3>{item.name}</h3>
              <p className="item-description">{item.description}</p>
              <div className="item-footer">
                <span className="item-price">₹{item.price}</span>
                <button 
                  className="add-to-cart-btn"
                  onClick={() => addToCart(item)}
                >
                  Add to Cart
                </button>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Menu;
